mapper.select:
SELECT mcpawcr.id, mcpawcr.create_time, mcpawcr.update_time, mcpawcr.bool_delete_enum, mcpawcr.version, mcpawcr.contract_project_id, mcpawcr.contract_project_assembling_welding_config_id, mcpawcr.contract_project_assembling_welding_config_detail_id, mcpawcr.initiator_id, mcpawcr.initiation_date, mcpawcr.reviewer_id, mcpawcr.review_date, mcpawcr.organization_inside_price, mcpawcr.organization_outside_price, mcpawcr.remark, mcpawcr.review_status, mcpawcr.review_remark, cp.short_name AS project_short_name, cp.serial_number AS project_serial_number, su.name AS initiator_name, su2.name AS reviewer_name, mbp.id AS process_id, mbp.name AS process_name, mac.classification AS artifact_classification_name, mcpawcl.pricing_manner, mcpawcld.comparison_operator_one, mcpawcld.number_one, mcpawcld.comparison_operator_two, mcpawcld.number_two, mcpawcl.measurement_manner FROM mes_contract_project_assembling_welding_config_review mcpawcr LEFT JOIN contract_project cp ON mcpawcr.contract_project_id = cp.id LEFT JOIN sys_user su ON su.id = mcpawcr.initiator_id LEFT JOIN sys_user su2 ON su2.id = mcpawcr.reviewer_id LEFT JOIN mes_contract_project_assembling_welding_config_link mcpawcl ON mcpawcl.id = mcpawcr.contract_project_assembling_welding_config_id LEFT JOIN mes_contract_project_assembling_welding_config_link_detail mcpawcld ON mcpawcld.id = mcpawcr.contract_project_assembling_welding_config_detail_id AND mcpawcld.bool_delete_enum = FALSE LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpawcl.process) > 0 LEFT JOIN mes_artifact_classification mac ON mac.id = mcpawcl.artifact_classification_id WHERE mcpawcr.bool_delete_enum = FALSE AND YEAR(mcpawcr.initiation_date) = #{queryDTOParam.year}
AND cp.short_name LIKE #{shortNameLike}
AND su.name LIKE #{initiatorNameLike}
AND su.name LIKE #{reviewerNameLike}
AND mac.classification LIKE #{artifactClassificationNameLike}
